182	void rmsnorm(float* o, float* x, float* weight, int size) {
183	    // calculate sum of squares
184	    float ss = 0.0f;
185	    for (int j = 0; j < size; j++) {
186	        ss += x[j] * x[j];
187	    }
188	    ss /= size;
189	    ss += 1e-5f;
190	    ss = 1.0f / sqrtf(ss);
191	    // normalize and scale
192	    for (int j = 0; j < size; j++) {
193	        o[j] = weight[j] * (ss * x[j]);
194	    }
195	}
196	
197	void softmax(float* x, int size) {
198	    // find max value (for numerical stability)
199	    float max_val = x[0];
200	    for (int i = 1; i < size; i++) {
201	        if (x[i] > max_val) {
202	            max_val = x[i];
203	        }
204	    }
205	    // exp and sum
206	    float sum = 0.0f;
207	    for (int i = 0; i < size; i++) {
208	        x[i] = expf(x[i] - max_val);
209	        sum += x[i];
210	    }
211	    // normalize
212	    for (int i = 0; i < size; i++) {
213	        x[i] /= sum;
214	    }
215	}
