573	// ----------------------------------------------------------------------------
574	// The Sampler, which takes logits and returns a sampled token
575	// sampling can be done in a few ways: greedy argmax, sampling, top-p sampling
576	
577	typedef struct {
578	    float prob;
579	    int index;
580	} ProbIndex; // struct used when sorting probabilities during top-p sampling
581	
582	typedef struct {
583	    int vocab_size;
584	    ProbIndex* probindex; // buffer used in top-p sampling
585	    float temperature;
586	    float topp;
587	    unsigned long long rng_state;
588	} Sampler;
589	
590	int sample_argmax(float* probabilities, int n) {
591	    // return the index that has the highest probability
592	    int max_i = 0;
593	    float max_p = probabilities[0];
594	    for (int i = 1; i < n; i++) {
595	        if (probabilities[i] > max_p) {
596	            max_i = i;
597	            max_p = probabilities[i];
598	        }
599	    }
600	    return max_i;
601	}
602	
603	int sample_mult(float* probabilities, int n, float coin) {
604	    // sample index from probabilities (they must sum to 1!)
605	    // coin is a random number in [0, 1), usually from random_f32()
606	    float cdf = 0.0f;
607	    for (int i = 0; i < n; i++) {
608	        cdf += probabilities[i];
609	        if (coin < cdf) {
610	            return i;
611	        }
612	    }
613	    return n - 1; // in case of rounding errors
614	}
615	
616	int compare(const void* a, const void* b) {
617	    ProbIndex* a_ = (ProbIndex*) a;
618	    ProbIndex* b_ = (ProbIndex*) b;
619	    if (a_->prob > b_->prob) return -1;
620	    if (a_->prob < b_->prob) return 1;
621	    return 0;
622	}
623	
624	int sample_topp(float* probabilities, int n, float topp, ProbIndex* probindex, float coin) {
625	    // top-p sampling (or "nucleus sampling") samples from the smallest set of
626	    // tokens that exceed probability topp. This way we never sample tokens that
627	    // have very low probabilities and are less likely to go "off the rails".
628	    // coin is a random number in [0, 1), usually from random_f32()
629	
630	    int n0 = 0;
631	    // quicksort indices in descending order of probabilities
632	    // values smaller than (1 - topp) / (n - 1) cannot be part of the result
633	    // so for efficiency we crop these out as candidates before sorting
634	    const float cutoff = (1.0f - topp) / (n - 1);
635	    for (int i = 0; i < n; i++) {
636	        if (probabilities[i] >= cutoff) {
637	            probindex[n0].index = i;
638	            probindex[n0].prob = probabilities[i];
639	            n0++;
640	        }
641	    }
642	    qsort(probindex, n0, sizeof(ProbIndex), compare);
643	
644	    // truncate the list where cumulative probability exceeds topp
645	    float cumulative_prob = 0.0f;
646	    int last_idx = n0 - 1; // in case of rounding errors consider all elements
647	    for (int i = 0; i < n0; i++) {
648	        cumulative_prob += probindex[i].prob;
649	        if (cumulative_prob > topp) {
650	            last_idx = i;
651	            break; // we've exceeded topp by including last_idx
652	        }
653	    }
654	
655	    // sample from the truncated list
656	    float r = coin * cumulative_prob;
657	    float cdf = 0.0f;
658	    for (int i = 0; i <= last_idx; i++) {
659	        cdf += probindex[i].prob;
660	        if (r < cdf) {
661	            return probindex[i].index;
662	        }
663	    }
664	    return probindex[last_idx].index; // in case of rounding errors
665	}
666	
667	void build_sampler(Sampler* sampler, int vocab_size, float temperature, float topp, unsigned long long rng_seed) {
668	    sampler->vocab_size = vocab_size;
669	    sampler->temperature = temperature;
670	    sampler->topp = topp;
671	    sampler->rng_state = rng_seed;
672	    // buffer only used with nucleus sampling; may not need but it's ~small
673	    sampler->probindex = malloc(sampler->vocab_size * sizeof(ProbIndex));
674	}
675	
676	void free_sampler(Sampler* sampler) {
677	    free(sampler->probindex);
678	}
679	
680	unsigned int random_u32(unsigned long long *state) {
681	    // xorshift rng: https://en.wikipedia.org/wiki/Xorshift#xorshift.2A
682	    *state ^= *state >> 12;
683	    *state ^= *state << 25;
684	    *state ^= *state >> 27;
685	    return (*state * 0x2545F4914F6CDD1Dull) >> 32;
686	}
687	float random_f32(unsigned long long *state) { // random float32 in [0,1)
688	    return (random_u32(state) >> 8) / 16777216.0f;
689	}
690	
691	int sample(Sampler* sampler, float* logits) {
692	    // sample the token given the logits and some hyperparameters
693	    int next;
694	    if (sampler->temperature == 0.0f) {
695	        // greedy argmax sampling: take the token with the highest probability
696	        next = sample_argmax(logits, sampler->vocab_size);
697	    } else {
698	        // apply the temperature to the logits
699	        for (int q=0; q<sampler->vocab_size; q++) { logits[q] /= sampler->temperature; }
700	        // apply softmax to the logits to get the probabilities for next token
701	        softmax(logits, sampler->vocab_size);
702	        // flip a (float) coin (this is our source of entropy for sampling)
703	        float coin = random_f32(&sampler->rng_state);
704	        // we sample from this distribution to get the next token
705	        if (sampler->topp <= 0 || sampler->topp >= 1) {
706	            // simply sample from the predicted probability distribution
707	            next = sample_mult(logits, sampler->vocab_size, coin);
708	        } else {
709	            // top-p (nucleus) sampling, clamping the least likely tokens to zero
710	            next = sample_topp(logits, sampler->vocab_size, sampler->topp, sampler->probindex, coin);
711	        }
712	    }
713	    return next;
714	}
