785	void read_stdin(const char* guide, char* buffer, size_t bufsize) {
786	    // read a line from stdin, up to but not including \n
787	    printf("%s", guide);
788	    if (fgets(buffer, bufsize, stdin) != NULL) {
789	        size_t len = strlen(buffer);
790	        if (len > 0 && buffer[len - 1] == '\n') {
791	            buffer[len - 1] = '\0'; // strip newline
792	        }
793	    }
794	}
