            a00 = vfmaq_f32(a00, vld1q_f32(r0 + j), x0);
            a01 = vfmaq_f32(a01, vld1q_f32(r0 + j + 4), x1);
            a10 = vfmaq_f32(a10, vld1q_f32(r1 + j), x0);
            a11 = vfmaq_f32(a11, vld1q_f32(r1 + j + 4), x1);
            a20 = vfmaq_f32(a20, vld1q_f32(r2 + j), x0);
            a21 = vfmaq_f32(a21, vld1q_f32(r2 + j + 4), x1);
            a30 = vfmaq_f32(a30, vld1q_f32(r3 + j), x0);
            a31 = vfmaq_f32(a31, vld1q_f32(r3 + j + 4), x1);
            a00 = vfmaq_f32(a00, vld1q_f32(r0 + j + 8), x2);
            a01 = vfmaq_f32(a01, vld1q_f32(r0 + j + 12), x3);
            a10 = vfmaq_f32(a10, vld1q_f32(r1 + j + 8), x2);
            a11 = vfmaq_f32(a11, vld1q_f32(r1 + j + 12), x3);
            a20 = vfmaq_f32(a20, vld1q_f32(r2 + j + 8), x2);
            a21 = vfmaq_f32(a21, vld1q_f32(r2 + j + 12), x3);
            a30 = vfmaq_f32(a30, vld1q_f32(r3 + j + 8), x2);
            a31 = vfmaq_f32(a31, vld1q_f32(r3 + j + 12), x3);
        }
        float32x4_t s0 = vaddq_f32(a00, a01), s1 = vaddq_f32(a10, a11);
        float32x4_t s2 = vaddq_f32(a20, a21), s3 = vaddq_f32(a30, a31);
        /* transpose-reduce 4 accumulators into one vector of 4 results */
        float32x4_t t01 = vpaddq_f32(s0, s1), t23 = vpaddq_f32(s2, s3);
        vst1q_f32(out + i, vpaddq_f32(t01, t23));
    }
    for (; i < d; i++) {
        const float *r = w + (size_t)i * n;
        float32x4_t a0 = vdupq_n_f32(0), a1 = a0;
        for (int j = 0; j < n; j += 8) {
            a0 = vfmaq_f32(a0, vld1q_f32(r + j), vld1q_f32(xv + j));
            a1 = vfmaq_f32(a1, vld1q_f32(r + j + 4), vld1q_f32(xv + j + 4));
        }
        out[i] = hsum(vaddq_f32(a0, a1));
    }
}

