     * were slower). Memory-bandwidth bound. */
    int i = 0;
    for (; i + 2 <= d; i += 2) {
        const float *r0 = w + (size_t)i * n, *r1 = r0 + n;
        float32x4_t a0 = vdupq_n_f32(0), a1 = a0, a2 = a0, a3 = a0;
        float32x4_t b0 = a0, b1 = a0, b2 = a0, b3 = a0;
